CREATE SCHEMA IF NOT EXISTS ai_workflow;
CREATE TABLE ai_workflow.workflow_stages(tenant TEXT NOT NULL,request TEXT NOT NULL,digest TEXT NOT NULL,stage TEXT NOT NULL,payload TEXT NOT NULL CHECK(payload IS JSON OBJECT),store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,request,stage));
CREATE TABLE ai_workflow.workflow_analyses(tenant TEXT NOT NULL,company TEXT NOT NULL,event TEXT NOT NULL,signature TEXT NOT NULL,payload TEXT NOT NULL CHECK(payload IS JSON OBJECT),store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,company,event));
CREATE TABLE ai_workflow.workflow_results(tenant TEXT NOT NULL,request TEXT NOT NULL,digest TEXT NOT NULL,payload TEXT NOT NULL CHECK(payload IS JSON OBJECT),store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,request));
CREATE TABLE ai_workflow.workflow_context_heads(tenant TEXT NOT NULL,company TEXT NOT NULL,version BIGINT NOT NULL CHECK(version>0),digest TEXT NOT NULL,store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,company));
CREATE TABLE ai_workflow.workflow_policy_heads(tenant TEXT NOT NULL,company TEXT NOT NULL,policy TEXT NOT NULL,version BIGINT NOT NULL CHECK(version>0),digest TEXT,store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,company,policy));
-- Execution leases protect AI artifacts, not Symfony's business job queue.
CREATE TABLE ai_workflow.workflow_executions(tenant TEXT NOT NULL,request TEXT NOT NULL,digest TEXT NOT NULL,owner TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('running','uncertain','complete')),lease_until TIMESTAMPTZ NOT NULL,store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,tenant,request));
CREATE TABLE ai_workflow.workflow_slots(slot INTEGER NOT NULL,owner TEXT NOT NULL,lease_until TIMESTAMPTZ NOT NULL,store_key TEXT NOT NULL DEFAULT current_setting('intelligence.store_key'),PRIMARY KEY(store_key,slot));
CREATE INDEX execution_lease ON ai_workflow.workflow_executions(store_key,state,lease_until);
